import { keccak256, toUtf8Bytes } from "ethers";

export const SIMULATION_MODES = {
  NORMAL: "NORMAL",
  EXCURSION: "EXCURSION",
  MANUAL: "MANUAL",
};

export const READING_STATUS = {
  OPTIMAL: "OPTIMAL",
  WARNING: "WARNING",
  EXCURSION: "EXCURSION",
};

export const SOURCE_LABELS = {
  NORMAL: "Software Simulator [Normal Range Model]",
  EXCURSION: "Software Simulator [Excursion Injection Model]",
  MANUAL: "Manual Test Input [Software Simulated]",
};

/**
 * Class managing software-only temperature simulation for vaccine batches.
 * HARDWARE DISCLAIMER: All readings generated by this simulator are software-generated
 * prototypes and DO NOT connect to physical sensor hardware (e.g. ESP32, DS18B20).
 */
export class TemperatureSimulator {
  constructor(batchConfig = {}) {
    this.batchId = batchConfig.batchId || "SIM-BATCH-001";
    this.vaccineName = batchConfig.vaccineName || "Standard Vaccine (2-8°C)";
    this.minTemp = typeof batchConfig.minTemp === "number" ? batchConfig.minTemp : 2;
    this.maxTemp = typeof batchConfig.maxTemp === "number" ? batchConfig.maxTemp : 8;
    this.checkpointRef = batchConfig.checkpointRef || "Transit Leg 1 - Refrigerated Carrier";

    this.mode = SIMULATION_MODES.NORMAL;
    this.isRunning = false;
    this.isPaused = false;
    this.timerId = null;
    this.intervalMs = 1500; // 1.5 seconds per sample

    this.readings = [];
    this.excursions = [];
    this.subscribers = new Set();

    // Internal simulation drift state
    this.currentDriftTemp = (this.minTemp + this.maxTemp) / 2;
    this.excursionStep = 0;
  }

  /**
   * Subscribe to new readings
   * @param {Function} callback (reading, summaryStats) => void
   */
  subscribe(callback) {
    this.subscribers.add(callback);
    return () => this.subscribers.delete(callback);
  }

  notifySubscribers(latestReading) {
    const summary = this.getSummaryStats();
    for (const callback of this.subscribers) {
      try {
        callback(latestReading, summary, this.readings);
      } catch (err) {
        console.error("Simulator subscriber error:", err);
      }
    }
  }

  setMode(mode) {
    if (Object.values(SIMULATION_MODES).includes(mode)) {
      this.mode = mode;
      this.excursionStep = 0;
    }
  }

  setInterval(ms) {
    this.intervalMs = Math.max(500, Math.min(ms, 10000));
    if (this.isRunning && !this.isPaused) {
      clearInterval(this.timerId);
      this.timerId = setInterval(() => this.generateNextReading(), this.intervalMs);
    }
  }

  setCheckpointRef(ref) {
    this.checkpointRef = ref || "Software Simulation Checkpoint";
  }

  start() {
    if (this.isRunning && !this.isPaused) return;

    this.isRunning = true;
    this.isPaused = false;

    // Generate immediate first sample if empty
    if (this.readings.length === 0) {
      this.generateNextReading();
    }

    clearInterval(this.timerId);
    this.timerId = setInterval(() => {
      this.generateNextReading();
    }, this.intervalMs);
  }

  pause() {
    if (!this.isRunning || this.isPaused) return;
    this.isPaused = true;
    clearInterval(this.timerId);
    this.timerId = null;
  }

  resume() {
    if (!this.isRunning || !this.isPaused) return;
    this.start();
  }

  reset() {
    this.pause();
    this.isRunning = false;
    this.isPaused = false;
    this.readings = [];
    this.excursions = [];
    this.currentDriftTemp = (this.minTemp + this.maxTemp) / 2;
    this.excursionStep = 0;
    this.notifySubscribers(null);
  }

  /**
   * Generates next reading based on active simulation mode
   */
  generateNextReading() {
    let temperature;
    let sourceLabel = SOURCE_LABELS[this.mode];

    if (this.mode === SIMULATION_MODES.NORMAL) {
      // Gaussian/random walk bounded nicely within [minTemp + buffer, maxTemp - buffer]
      const targetMid = (this.minTemp + this.maxTemp) / 2;
      const step = (Math.random() - 0.48) * 0.4; // slight random fluctuation
      this.currentDriftTemp += step;

      // Keep within bounds with dampening
      if (this.currentDriftTemp > this.maxTemp - 0.5) {
        this.currentDriftTemp -= 0.6;
      } else if (this.currentDriftTemp < this.minTemp + 0.5) {
        this.currentDriftTemp += 0.6;
      }
      temperature = Number(this.currentDriftTemp.toFixed(2));
    } else if (this.mode === SIMULATION_MODES.EXCURSION) {
      // Create a progressive excursion scenario:
      // Steps 1-2: Normal
      // Steps 3-7: Rapid spike breaching max limit (e.g. cooling failure)
      // Steps 8+: Elevated out-of-range temperature
      this.excursionStep += 1;
      if (this.excursionStep <= 2) {
        temperature = Number(((this.minTemp + this.maxTemp) / 2 + (Math.random() - 0.5) * 0.5).toFixed(2));
      } else if (this.excursionStep <= 6) {
        const spikeIncrement = (this.maxTemp - this.minTemp) * 0.35 + 1.2;
        this.currentDriftTemp += spikeIncrement;
        temperature = Number(this.currentDriftTemp.toFixed(2));
      } else {
        // High persistent breach
        const breachBaseline = this.maxTemp + 3.5 + Math.random() * 2.0;
        temperature = Number(breachBaseline.toFixed(2));
      }
    } else {
      // In manual mode, auto-tick doesn't run
      return;
    }

    this.recordReading(temperature, sourceLabel);
  }

  /**
   * Manual mode input submission
   */
  submitManualReading(temperatureValue, manualCheckpoint) {
    const tempNum = Number(parseFloat(temperatureValue).toFixed(2));
    const ref = manualCheckpoint || this.checkpointRef;
    const reading = this.recordReading(tempNum, SOURCE_LABELS.MANUAL, ref);
    return reading;
  }

  /**
   * Core reading record and excursion classification
   */
  recordReading(temperature, sourceLabel, customCheckpoint) {
    const isBelow = temperature < this.minTemp;
    const isAbove = temperature > this.maxTemp;
    const isExcursion = isBelow || isAbove;

    // Warning buffer within 10% of limits
    const rangeSpan = Math.abs(this.maxTemp - this.minTemp) || 1;
    const isWarning =
      !isExcursion &&
      (temperature <= this.minTemp + rangeSpan * 0.1 ||
        temperature >= this.maxTemp - rangeSpan * 0.1);

    const status = isExcursion
      ? READING_STATUS.EXCURSION
      : isWarning
      ? READING_STATUS.WARNING
      : READING_STATUS.OPTIMAL;

    const simulatedTimestamp = new Date();
    const reading = {
      id: `sample-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
      batchId: this.batchId,
      temperature,
      timestamp: simulatedTimestamp.toISOString(),
      timestampUnix: Math.floor(simulatedTimestamp.getTime() / 1000),
      timeLabel: simulatedTimestamp.toLocaleTimeString(),
      source: sourceLabel,
      checkpointReference: customCheckpoint || this.checkpointRef,
      minPermitted: this.minTemp,
      maxPermitted: this.maxTemp,
      status,
      isExcursion,
      violationType: isBelow ? "SUB_ZERO_OR_FREEZING_VIOLATION" : isAbove ? "HEAT_BREACH_VIOLATION" : null,
    };

    this.readings.push(reading);

    if (isExcursion) {
      this.excursions.push(reading);
    }

    this.notifySubscribers(reading);
    return reading;
  }

  /**
   * Calculate summary statistics across all readings
   */
  getSummaryStats() {
    if (this.readings.length === 0) {
      return {
        sampleCount: 0,
        minObserved: null,
        maxObserved: null,
        avgObserved: null,
        excursionCount: 0,
        hasExcursion: false,
        prototypeAssessment: "AWAITING_SIMULATION",
      };
    }

    const temps = this.readings.map((r) => r.temperature);
    const minObserved = Math.min(...temps);
    const maxObserved = Math.max(...temps);
    const sum = temps.reduce((acc, curr) => acc + curr, 0);
    const avgObserved = Number((sum / temps.length).toFixed(2));
    const excursionCount = this.excursions.length;
    const hasExcursion = excursionCount > 0;

    return {
      sampleCount: this.readings.length,
      minObserved,
      maxObserved,
      avgObserved,
      excursionCount,
      hasExcursion,
      // Clear academic prototype label as mandated by specification
      prototypeAssessment: hasExcursion
        ? "PROTOTYPE_ASSESSMENT_EXCURSION_FLAGGED"
        : "PROTOTYPE_ASSESSMENT_WITHIN_BOUNDS",
      disclaimer: "ACADEMIC PROTOTYPE ONLY: Simulated reading analysis. Not qualified for physical medical validation.",
    };
  }

  /**
   * Generates a tamper-evident evidence package with cryptographic Keccak256 hash
   * ready to be anchored to the smart contract.
   */
  generateEvidencePackage(customNotes = "") {
    const stats = this.getSummaryStats();
    const payload = {
      batchId: this.batchId,
      vaccineName: this.vaccineName,
      minPermitted: this.minTemp,
      maxPermitted: this.maxTemp,
      checkpointReference: this.checkpointRef,
      startTime: this.readings.length > 0 ? this.readings[0].timestamp : null,
      endTime: this.readings.length > 0 ? this.readings[this.readings.length - 1].timestamp : null,
      sampleCount: stats.sampleCount,
      minObserved: stats.minObserved,
      maxObserved: stats.maxObserved,
      avgObserved: stats.avgObserved,
      excursionCount: stats.excursionCount,
      hasExcursion: stats.hasExcursion,
      notes: customNotes || "Software simulated temperature batch",
      samples: this.readings.map((r) => ({
        t: r.temperature,
        ts: r.timestamp,
        s: r.status,
      })),
      disclaimer: "SOFTWARE SIMULATION EVIDENCE: Generated for educational blockchain demonstration.",
    };

    const canonicalJson = JSON.stringify(payload);
    const evidenceHash = keccak256(toUtf8Bytes(canonicalJson));

    return {
      payload,
      canonicalJson,
      evidenceHash,
      stats,
    };
  }
}
